205		var finalText string
206		sawFinalMessage := false
207		var agentErrors []string
208		malformedEvent := false
209		for lineNumber, line := range strings.Split(raw, "\n") {
210			line = strings.TrimSpace(line)
211			if line == "" {
212				continue
213			}
214			if !strings.HasPrefix(line, "{") {
215				continue
216			}
217			var event struct {
218				Type  string           `json:"type"`
219				Usage distillUsageJSON `json:"usage"`
220				Item  struct {
221					Type    string `json:"type"`
222					Text    string `json:"text"`
223					Message string `json:"message"`
224				} `json:"item"`
225			}
226			if err := json.Unmarshal([]byte(line), &event); err != nil {
227				malformedEvent = true
228				continue
229			}
230			switch event.Type {
231			case "item.completed":
232				switch event.Item.Type {
233				case "agent_message":
234					sawFinalMessage = true
235					finalText = event.Item.Text
236				case "error":
237					agentErrors = append(agentErrors, event.Item.Message)
238				}
239			case "turn.completed":
240				if err := event.Usage.validate(); err != nil {
241					usage.InputReported = false
242					usage.OutputReported = false
243					return "", usage, fmt.Errorf("codex usage on line %d: %w", lineNumber+1, err)
244				}
245				event.Usage.addTo(&usage)
246			}
247		}
248		if malformedEvent {
249			// Fact output can still be valid, but an unreadable event may have held
250			// additional usage. Preserve observed counts without claiming completeness.
251			usage.InputReported = false
252			usage.OutputReported = false
253		}
254		if !sawFinalMessage {
255			if len(agentErrors) > 0 {
256				return "", usage, fmt.Errorf("codex returned an error: %s", strings.Join(agentErrors, "; "))
257			}
258			return "", usage, fmt.Errorf("codex JSONL contained no final agent message")
259		}
